function [prdData, info] = predict_Aptenodytes_forsteri(par, data, auxData)    % unpack par, data, auxData  cPar = parscomp_st(par); vars_pull(par);   vars_pull(cPar);  vars_pull(data);  vars_pull(auxData);    if f_000<1e-3 || f_010<1e-3 || f_020<1e-3 || f_030<1e-3 || f_040<1e-3 || f_050<1e-3 || f_060<1e-3 || f_070<1e-3 || f_080<1e-3 || f_090<1e-3 || f_100<1e-3 || ...      f_110<1e-3 || f_120<1e-3 || f_130<1e-3 || f_140<1e-3 || f_150<1e-3 || f_160<1e-3 || f_170<1e-3 || f_180<1e-3 || ...        f_000>5.5 || f_010>3.5 || f_020>3.5 || f_030>3.5 || f_040>3.5 || f_050>3.5 || f_060>3.5 || f_070>3.5 || f_080>3.5 || f_090>3.5 || f_100>4.5 || ...          f_110>4.5 || f_120>3.5 || f_130>3.5 || f_140>3.5 || f_150>3.5 || f_160>3.5 || f_170>3.5 || f_180>3.5     info = 0; prdData = []; return  end    % compute temperature correction factors  TC_ab = tempcorr(temp.ab, T_ref, T_A);  TC = tempcorr(temp.am, T_ref, T_A); kT_M = TC * k_M;    % zero-variate data  % life cycle  pars_tx = [g; k; l_T; v_Hb; v_Hx];  % compose parameter vector  tau_x = get_tp(pars_tx, f);   pars_tp = [g; k; l_T; v_Hb; v_Hp];  % compose parameter vector  [tau_p, tau_b, l_p, l_b, info] = get_tp(pars_tp, f);  % -, scaled times & lengths  if ~info; prdData = []; return; end    % initial  E_0 = p_Am * initial_scaled_reserve(f, [V_Hb, g, k_J, k_M, v]);  Ww_0 = E_0/ mu_E * w_E/ d_E; % g, initial egg weight    % birth  L_b = L_m * l_b;                  % cm, structural length at birth at f  Ww_b = L_b^3 * (1 + f * ome);       % g, wet weight at birth at f   aT_b = tau_b/ k_M/ TC_ab;     % d, age at birth at f and T    % fledging  tT_x = (tau_x - tau_b)/ kT_M;         % d, time since birth at fledging  % puberty  tT_p = (tau_p - tau_b)/ kT_M;         % d, time since birth at puberty  % ultimate  l_i = f - l_T;                    % -, scaled ultimate length  L_i = L_m * l_i;                  % cm, ultimate structural length at f  Ww_i = L_i^3 * (1 + f * ome);       % g, ultimate wet weight    % reproduction  pars_R = [kap; kap_R; g; k_J; k_M; L_T; v; U_Hb; U_Hp]; % compose parameter vector at T  RT_i = TC * reprod_rate(L_i, f, pars_R);                % #/d, ultimate reproduction rate at T  % life span  pars_tm = [g; l_T; h_a/ k_M^2; s_G];  % compose parameter vector at T_ref  tau_m = get_tm_s(pars_tm, f, l_b);      % -, scaled mean life span at T_ref  aT_m = tau_m/ kT_M;                     % d, mean life span at T    % pack to output  prdData.ab = aT_b;  prdData.tx = tT_x;  prdData.tp = tT_p;  prdData.tR = t_R;  prdData.am = aT_m;  prdData.Ww0 = Ww_0;  prdData.Wwb = Ww_b;  prdData.Wwi = Ww_i;  prdData.Ri = RT_i;    % uni-variate data    tf = [10*(0:18); f_000 f_010 f_020 f_030 f_040 f_050 f_060 f_070 f_080 f_090 f_100 f_110 f_120 f_130 f_140 f_150 f_160 f_170 f_180]';  tf(:,1) = tf(:,1) * kT_M;  tvel = get_tp(pars_tp, tf, [tau_b 1 l_b], tW(:,1)*kT_M);  EWw = (L_m * tvel(:,4)).^3 .* (1 + tvel(:,3) * ome);   % g, weight    % pack to output  prdData.tW = EWw;end